import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.ePeAWSvT.js";const m=JSON.parse('{"title":"Central Support","description":"","frontmatter":{},"headers":[],"relativePath":"guide/support.md","filePath":"guide/support.md"}'),o={name:"guide/support.md"};function i(l,e,n,p,u,d){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="central-support" tabindex="-1">Central Support <a class="header-anchor" href="#central-support" aria-label="Permalink to &quot;Central Support&quot;">​</a></h1><p>Central offers two support channels. Which one you use depends on whether the platform is down or you need help with a specific issue.</p><table tabindex="0"><thead><tr><th>Situation</th><th>Channel</th></tr></thead><tbody><tr><td>Central is unavailable or a system-wide outage is in progress</td><td>Call the Service Desk at <strong>(513) 967-2267</strong></td></tr><tr><td>Failed payloads, data discrepancies, access problems, enhancement requests</td><td>Email <strong><a href="mailto:support@teamcentral.ai" target="_blank" rel="noreferrer">support@teamcentral.ai</a></strong></td></tr></tbody></table><h2 id="system-outage-support" tabindex="-1">System Outage Support <a class="header-anchor" href="#system-outage-support" aria-label="Permalink to &quot;System Outage Support&quot;">​</a></h2><p>In the event of a Central system outage, follow these steps for the fastest resolution:</p><ol><li><strong>Call the Service Desk:</strong> Dial <strong>(513) 967-2267</strong>.</li><li><strong>Provide the following information:</strong><ul><li>Your Name</li><li>Your Contact Number</li><li>Company Name</li><li>A detailed description of the outage, including any additional relevant details.</li></ul></li><li><strong>If Immediate Assistance Isn&#39;t Available:</strong><ul><li>The Service Desk will escalate your request to TeamCentral&#39;s Technical Team.</li><li>You will be contacted as soon as possible to address the issue.</li></ul></li></ol><h2 id="support-enhancement-requests" tabindex="-1">Support &amp; Enhancement Requests <a class="header-anchor" href="#support-enhancement-requests" aria-label="Permalink to &quot;Support &amp; Enhancement Requests&quot;">​</a></h2><p>For issues like failed payloads, data discrepancies, access problems, or enhancement requests, please follow these steps:</p><ol><li><strong>Email the Service Desk:</strong> Send your request to <strong><a href="mailto:support@teamcentral.ai" target="_blank" rel="noreferrer">support@teamcentral.ai</a></strong></li><li><strong>Email Subject Line:</strong> Include your company name and a brief description of the issue.</li><li><strong>Provide the following details in the email:</strong><ul><li>Your Name</li><li>Your Contact Number</li><li>Company Name</li><li>A detailed description of the issue or enhancement request, along with any relevant information.</li></ul></li><li><strong>What to Expect:</strong><ul><li>You will receive an immediate acknowledgment of your request.</li><li>A technical specialist will be assigned to investigate and address your issue promptly.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">NOTE</p><p>Including specifics from the platform helps the technical specialist reproduce your issue faster. Useful details include the message ID from <a href="./monitor-messages.html">Messages</a>, the entry from <a href="./monitor-error-logs.html">Error Logs</a>, the data hub and endpoint names, and the environment you were working in.</p></div>',10)])])}const h=t(o,[["render",i]]);export{m as __pageData,h as default};
